// src/App.js
import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import EmployeeList from "./components/EmployeeList";
import EmployeeForm from "./components/EmployeeForm";
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import { Container, Box, Typography } from '@mui/material';
import LoginPage from './components/LoginPage';
import ProtectedRoute from './components/ProtectedRoute';
import RegisterPage from './components/RegisterPage';
import UserList from './components/UserList';

function AppWrapper() {
  const location = useLocation();
  const isLoginPage = location.pathname === '/login';

  return (
    <Box display="flex" flexDirection="column" minHeight="100vh">
      {!isLoginPage && <Navbar />}

      <Container maxWidth="lg" sx={{ flex: 1, mt: 4 }}>
        <Routes>
          <Route path="/login" element={<LoginPage />} />
          <Route path="/register" element={<RegisterPage />} />
          <Route path="/" element={<ProtectedRoute><EmployeeList /></ProtectedRoute>} />
          <Route path="/users" element={
              <ProtectedRoute requiredRole="ADMIN">
                <UserList />
              </ProtectedRoute>
            }
          />
          <Route path="/add" element={<ProtectedRoute><EmployeeForm /></ProtectedRoute>} />
          <Route path="/edit/:id" element={<ProtectedRoute><EmployeeForm /></ProtectedRoute>} />
          <Route path="*" element={<Typography>404 - Page Not Found</Typography>} />
        </Routes>
      </Container>

      {!isLoginPage && <Footer />}
    </Box>
  );
}

function App() {
  return (
    <Router>
      <AppWrapper />
    </Router>
  );
}

export default App;
