// src/components/Navbar.js

import React, { useState } from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  IconButton,
  Menu,
  MenuItem,
} from '@mui/material';
import { Link, useNavigate } from 'react-router-dom';
import LogoutIcon from '@mui/icons-material/Logout';
import MenuIcon from '@mui/icons-material/Menu';
import { getUserRoles, isTokenExpired, getUserInfo } from '../utils/auth'; // ✅ make sure this is imported


function capitalize(name) {
  if (!name) return '';
  return name.charAt(0).toUpperCase() + name.slice(1);
}

function Navbar() {
  const navigate = useNavigate();
  const token = localStorage.getItem("token");
  const isAuthenticated = token && !isTokenExpired(token);
  //const role = getUserRole();
  const userInfo = getUserInfo(); // ✅ get decoded username or first/last name
  
  const roles = getUserRoles();
  const isAdmin = roles.includes("ADMIN");

  console.log("Navbar Role:", roles);
  console.log("Navbar UserInfo:", userInfo);
  console.log("Navbar isAdmin:", isAdmin);

   // For dropdown menu
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);
  const handleMenuClick = (event) => setAnchorEl(event.currentTarget);
  const handleMenuClose = () => setAnchorEl(null);

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login", { replace: true });
  };

  return (
    <AppBar position="static" color="primary">
      <Toolbar>
        {/* App Title */}
        <Typography variant="h6" sx={{ flexGrow: 1, fontWeight: 'bold' }}>
          Employee Manager
        </Typography>

        {/* Greeting if logged in */}
        {isAuthenticated && userInfo && (
          <Typography variant="body1" sx={{ marginRight: 2 }}>
            Hi, {userInfo.firstName
              ? `${capitalize(userInfo.firstName)} ${capitalize(userInfo.lastName || '')}`
              : capitalize(userInfo.sub || userInfo.username)}
          </Typography>
        )}

        {/* Navigation Links */}
        {/* {isAuthenticated && (
          <>
            <Button color="inherit" component={Link} to="/">
              Employee List
            </Button>

            <Button color="inherit" component={Link} to="/register">
              Register
            </Button>

            {role === "ADMIN" && (
              <Button color="inherit" component={Link} to="/add">
                + Add Employee
              </Button>
            )}

            <IconButton color="inherit" onClick={handleLogout} sx={{ ml: 2 }}>
              <LogoutIcon />
            </IconButton>
          </>
        )} */}

        {/* Menu Dropdown */}
        {isAuthenticated && (
          <>
            <IconButton
              color="inherit"
              onClick={handleMenuClick}
              size="large"
            >
              <MenuIcon />
            </IconButton>

            <Menu anchorEl={anchorEl} open={open} onClose={handleMenuClose}>
              <MenuItem component={Link} to="/" onClick={handleMenuClose}>
                Employee List
              </MenuItem>

             {isAdmin && (
               <MenuItem component={Link} to="/users" onClick={handleMenuClose}>
                User List
              </MenuItem>
            )}
            {isAdmin && (
                <MenuItem component={Link} to="/add" onClick={handleMenuClose}>
                  + Add Employee
                </MenuItem>
              )}
            </Menu>
             <IconButton color="inherit" onClick={handleLogout} sx={{ ml: 2 }}>
              <LogoutIcon />
            </IconButton>
          </>
        )}
      </Toolbar>
    </AppBar>
  );
}



export default Navbar;
