import React, { useEffect, useState } from 'react';
import {
  Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, Paper, IconButton, Typography, Box, Button,
  CircularProgress
} from '@mui/material';
import { Edit, Delete } from '@mui/icons-material';
import { getAllEmployees, deleteEmployee } from '../services/employeeService';
import { useNavigate } from 'react-router-dom';
import { getUserRole, getUserRoles } from '../utils/auth';

function EmployeeList() {
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const roles = getUserRoles();
  const isAdmin = roles.includes("ADMIN");

  console.log("EmployeeList Role:", roles);
  console.log("EmployeeList isAdmin:", isAdmin);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      setLoading(true);
      const response = await getAllEmployees();
      setEmployees(response.data);
    } catch (err) {
      console.error("Failed to fetch employees:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (id) => {
    navigate(`/edit/${id}`);
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to delete this employee?")) {
      try {
        await deleteEmployee(id);
        fetchEmployees(); // Refresh list
      } catch (err) {
        console.error("Failed to delete employee:", err);
        alert("Failed to delete employee.");
      }
    }
  };

  return (
    <Box mt={4}>
      <Typography variant="h5" gutterBottom>
        Employee List
      </Typography>

      {/* Show Add button for ADMIN */}
      {isAdmin && (
        <Box display="flex" justifyContent="flex-end" mb={2}>
          <Button
            variant="contained"
            color="primary"
            onClick={() => navigate('/add')}
          >
            + Add Employee
          </Button>
        </Box>
      )}

      {/* Loading indicator */}
      {loading ? (
        <Box display="flex" justifyContent="center" mt={4}>
          <CircularProgress />
        </Box>
      ) : (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell><strong>First Name</strong></TableCell>
                <TableCell><strong>Last Name</strong></TableCell>
                <TableCell><strong>Email</strong></TableCell>
                <TableCell><strong>Department</strong></TableCell>
                <TableCell><strong>Role</strong></TableCell>
                {isAdmin && <TableCell><strong>Actions</strong></TableCell>}
              </TableRow>
            </TableHead>
            <TableBody>
              {employees.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    No employees found.
                  </TableCell>
                </TableRow>
              ) : (
                employees.map((emp) => (
                  <TableRow key={emp.id}>
                    <TableCell>{emp.firstName}</TableCell>
                    <TableCell>{emp.lastName}</TableCell>
                    <TableCell>{emp.email}</TableCell>
                    <TableCell>{emp.department}</TableCell>
                    <TableCell>{emp.role}</TableCell>
                    {isAdmin && (
                      <TableCell>
                        <IconButton color="primary" onClick={() => handleEdit(emp.id)}>
                          <Edit />
                        </IconButton>
                        <IconButton color="error" onClick={() => handleDelete(emp.id)}>
                          <Delete />
                        </IconButton>
                      </TableCell>
                    )}
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Box>
  );
}

export default EmployeeList;
