import React, { useState, useEffect } from 'react';
import {
  Container, Paper, Typography, TextField, Button, Box, Snackbar, Alert,
} from '@mui/material';
import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';

function LoginPage() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [loginSuccess, setLoginSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) navigate('/');
  }, []);

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await axios.post('http://localhost:8081/auth/token', {
        username,
        password,
      }, {
        headers: { 'Content-Type': 'application/json' }
      });

      const token = response.data.token;
      localStorage.setItem('token', token); // store raw token

      console.log("LoginPage.js--handleLogin:token="+token);

      setSnackbar({ open: true, message: 'Login successful', severity: 'success' });
      setLoginSuccess(true);
    } catch (error) {
      console.error("Login failed:", error);
      setSnackbar({
        open: true,
        message:
          error.response?.status === 401
            ? 'Invalid username or password'
            : 'Login failed. Please try again.',
        severity: 'error'
      });
      setPassword('');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (loginSuccess) {
      navigate('/');
    }
  }, [loginSuccess, navigate]);

  return (
    <Container maxWidth="sm">
      <Paper elevation={3} sx={{ mt: 8, p: 4 }}>
        <Typography variant="h5" gutterBottom>Login</Typography>
        <Box component="form" onSubmit={handleLogin}>
          <TextField
            label="Username"
            fullWidth required
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            margin="normal"
          />
          <TextField
            label="Password"
            type="password"
            fullWidth required
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            margin="normal"
          />
          <Box sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
            <Button type="submit" variant="contained" color="primary" disabled={loading}>
              {loading ? "Logging in..." : "Login"}
            </Button>
          </Box>
          {/* ✅ Registration link */}
          <Typography variant="body2" sx={{ mt: 2 }}>
                Don't have an account? <Link to="/register">Register here</Link>
              </Typography>
        </Box>
      </Paper>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert severity={snackbar.severity} variant="filled">
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
}

export default LoginPage;
