import axios from 'axios';

const API_BASE_URL = "/employees";
const API_BASE_URL_ALL = "/employees/all";

// Reusable function to include Authorization header
const authHeader = () => ({
  headers: {
    Authorization: localStorage.getItem('token') || '',
  },
});

// Public GET — no auth needed
//export const getAllEmployees = () => axios.get(API_BASE_URL_ALL);
export const getAllEmployees = () => axios.get(API_BASE_URL_ALL, authHeader());

//export const getEmployeeById = (id) => axios.get(`${API_BASE_URL}/${id}`);

export const getEmployeeById = (id) =>
  axios.get(`${API_BASE_URL}/${id}`, authHeader());

// Protected APIs — require JWT
export const createEmployee = (employee) =>
  axios.post(API_BASE_URL, employee, authHeader());

export const updateEmployee = (id, employee) =>
  axios.put(`${API_BASE_URL}/${id}`, employee, authHeader());

export const deleteEmployee = (id) =>
  axios.delete(`${API_BASE_URL}/${id}`, authHeader());


