// src/components/UserList.js
import React, { useEffect, useState } from 'react';
import {
  Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, Paper, IconButton, Typography, Box, Button, Dialog, DialogTitle, DialogContent, TextField, DialogActions
} from '@mui/material';
import { Edit, Delete } from '@mui/icons-material';
import axios from 'axios';
import { getUserRole, getUserRoles } from '../utils/auth';
import { useNavigate } from 'react-router-dom';

function UserList() {
  const [users, setUsers] = useState([]);
  const [editingUser, setEditingUser] = useState(null);
  const [open, setOpen] = useState(false);
  const roles = getUserRoles();
  const navigate = useNavigate();
  const isAdmin = roles.includes("ADMIN");

  console.log("UserList.js is calling ::roles==="+roles);
  console.log("UserList.js isAdmin:", isAdmin);

  useEffect(() => {
    if (!isAdmin) {
      navigate('/'); // redirect non-admins
      return;
    }
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const token = localStorage.getItem("token");
    const res = await axios.get("http://localhost:8081/users", {
      headers: { Authorization: `Bearer ${token}` }
    });
    setUsers(res.data);
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setOpen(true);
  };

  const handleUpdate = async () => {
    const token = localStorage.getItem("token");
    await axios.put(`http://localhost:8081/users/${editingUser.id}`, editingUser, {
      headers: { Authorization: token }
    });
    setOpen(false);
    fetchUsers();
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure?")) {
      const token = localStorage.getItem("token");
      await axios.delete(`http://localhost:8081/users/${id}`, {
        headers: { Authorization: token }
      });
      fetchUsers();
    }
  };

  return (
    <Box mt={4}>
      <Typography variant="h5" gutterBottom>User List</Typography>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell><strong>Username</strong></TableCell>
              <TableCell><strong>Role</strong></TableCell>
              <TableCell><strong>Actions</strong></TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {users.map((u) => (
              <TableRow key={u.id}>
                <TableCell>{u.username}</TableCell>
                <TableCell>{u.role}</TableCell>
                <TableCell>
                  <IconButton onClick={() => handleEdit(u)}><Edit /></IconButton>
                  <IconButton onClick={() => handleDelete(u.id)}><Delete color="error" /></IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Edit Dialog */}
      <Dialog open={open} onClose={() => setOpen(false)}>
        <DialogTitle>Edit User</DialogTitle>
        <DialogContent>
          <TextField
            label="Username"
            fullWidth
            margin="normal"
            value={editingUser?.username || ''}
            onChange={(e) =>
              setEditingUser({ ...editingUser, username: e.target.value })
            }
          />
          <TextField
            label="Role"
            fullWidth
            margin="normal"
            value={editingUser?.role || ''}
            onChange={(e) =>
              setEditingUser({ ...editingUser, role: e.target.value.toUpperCase() })
            }
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleUpdate}>Update</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

export default UserList;
