import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { isTokenExpired, getUserRoles } from '../utils/auth';

const ProtectedRoute = ({ children, requiredRole }) => {
  const token = localStorage.getItem('token');
  const location = useLocation();
  console.log('calling ProtectedRoute.js:token==='+token);
   console.log('calling ProtectedRoute.js:location==='+location);
    console.log('calling ProtectedRoute.js:requireRole==='+requiredRole);

  // ✅ Correctly pass the token to check if it's expired
  if (!token || isTokenExpired(token)) {
    localStorage.removeItem('token');
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  if (requiredRole && !getUserRoles().includes(requiredRole)) {
    return <Navigate to="/" />; // or return a 403 component
  }

  return children;
};

export default ProtectedRoute;

