import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Container,
  Grid,
  TextField,
  Typography,
  Paper,
  MenuItem,
  Snackbar,
  Alert,
  CircularProgress,
} from '@mui/material';
import { createEmployee, getEmployeeById, updateEmployee } from '../services/employeeService';
import { useNavigate, useParams } from 'react-router-dom';

function EmployeeForm() {
  const [employee, setEmployee] = useState({
    firstName: '',
    lastName: '',
    email: '',
    department: '',
    role: ''
  });

  const [errors, setErrors] = useState({});
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();
  const { id } = useParams();

  useEffect(() => {
    if (id) {
      getEmployeeById(id).then(res => setEmployee(res.data));
    }
  }, [id]);

  const validate = () => {
    const newErrors = {};
    if (!employee.firstName.trim()) newErrors.firstName = 'First name is required';
    if (!employee.lastName.trim()) newErrors.lastName = 'Last name is required';
    if (!employee.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/^[\w-.]+@([\w-]+\.)+[\w-]{2,4}$/i.test(employee.email)) {
      newErrors.email = 'Invalid email format';
    }
    if (!employee.department.trim()) newErrors.department = 'Department is required';
    if (!employee.role.trim()) newErrors.role = 'Role is required';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setEmployee(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    try {
      setLoading(true);
      if (id) {
        await updateEmployee(id, employee);
        setSnackbar({ open: true, message: 'Employee updated successfully!', severity: 'success' });
      } else {
        await createEmployee(employee);
        setSnackbar({ open: true, message: 'Employee created successfully!', severity: 'success' });
      }
      setTimeout(() => navigate('/'), 1500);
    } catch (error) {
      console.error(error);
      setSnackbar({ open: true, message: 'Something went wrong!', severity: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    navigate('/');
  };

  const handleCloseSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  return (
    <Container maxWidth="lg">
      <Paper elevation={3} sx={{ p: 4, mt: 4 }}>
        <Typography variant="h5" gutterBottom>
          {id ? 'Edit Employee' : 'Add New Employee'}
        </Typography>

        <Box component="form" onSubmit={handleSubmit} noValidate sx={{ mt: 2 }}>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <TextField
                label="First Name"
                name="firstName"
                value={employee.firstName}
                onChange={handleChange}
                required
                fullWidth
                error={!!errors.firstName}
                helperText={errors.firstName}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Last Name"
                name="lastName"
                value={employee.lastName}
                onChange={handleChange}
                required
                fullWidth
                error={!!errors.lastName}
                helperText={errors.lastName}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="Email"
                name="email"
                type="email"
                value={employee.email}
                onChange={handleChange}
                required
                fullWidth
                error={!!errors.email}
                helperText={errors.email}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                select
                label="Department"
                name="department"
                value={employee.department}
                onChange={handleChange}
                required
                fullWidth
                error={!!errors.department}
                helperText={errors.department}
              >
                <MenuItem value=""><em>None</em></MenuItem>
                <MenuItem value="Software">Software</MenuItem>
                <MenuItem value="IT">IT</MenuItem>
                <MenuItem value="Finance">Finance</MenuItem>
                <MenuItem value="HR">HR</MenuItem>
                <MenuItem value="Sales">Sales</MenuItem>
              </TextField>
            </Grid>
            <Grid item xs={12}>
              <TextField
                select
                label="Role"
                name="role"
                value={employee.role}
                onChange={handleChange}
                required
                fullWidth
                error={!!errors.role}
                helperText={errors.role}
              >
                <MenuItem value=""><em>None</em></MenuItem>
                <MenuItem value="Admin">Admin</MenuItem>
                <MenuItem value="User">User</MenuItem>
              </TextField>
            </Grid>
          </Grid>

          <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end', gap: 2 }}>
            <Button type="submit" variant="contained" color="primary" disabled={loading}>
              {loading ? <CircularProgress size={24} color="inherit" /> : 'Save'}
            </Button>
            <Button type="button" variant="outlined" color="secondary" onClick={handleCancel} disabled={loading}>
              Cancel
            </Button>
          </Box>
        </Box>
      </Paper>

      {/* Snackbar for feedback */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert severity={snackbar.severity} onClose={handleCloseSnackbar} variant="filled">
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
}

export default EmployeeForm;


